draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30, H/2 + 80);
  ctx.stroke();

  // breathing line
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 120);
  ctx.lineTo(W/2 + 50, H/2 + 120 + 20 * Math.sin(t));
  ctx.stroke();

  // life and death text
  ctx.font = '24px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillText('Life', W/2 - 70, H/2 + 150 + 10 * Math.sin(t));
  ctx.textAlign = 'right';
  ctx.fillText('Death', W/2 + 70, H/2 + 150 + 10 * Math.cos(t));

  ctx.restore();
}
